import{_ as s,o as t,a as n,b as p}from"./app.DKoEZOcr.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵搬出辅助配置接口","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_aux_config/cube_store_aux_config"},{"text":"SetFixpipeNz2ndFlag","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_aux_config/SetFixpipeNz2ndFlag"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_aux_config/SetFixpipeNz2ndFlag.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_aux_config/SetFixpipeNz2ndFlag.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),d={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_aux_config/SetFixpipeNz2ndFlag.md"};function e(i,a,l,c,r,h){return t(),n("div",null,[...a[0]||(a[0]=[p(`<div><article class="markdown-body"><h1>SetFixpipeNz2ndFlag<a id="ZH-CN_TOPIC_0000002569070993"></a></h1><h2 id="产品支持情况">产品支持情况<a id="zh-cn_topic_0000002516209232_section18204144912492"></a><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：支持</li></ul></div><h2 id="功能说明">功能说明<a id="zh-cn_topic_0000002516209232_section618mcpsimp"></a><a class="header-anchor" href="#功能说明">​</a></h2><p>DataCopy数据搬运（<a href="../cube_compute_store/Fixpipe_L0CToGM.html">L0C Buffer-&gt;GM</a>）过程中进行随路格式转换（NZ格式转换为ND格式）时，通过调用该接口设置格式转换的相关配置。</p><h2 id="函数原型">函数原型<a id="zh-cn_topic_0000002516209232_section620mcpsimp"></a><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">SetFixpipeNz2ndFlag</span><span class="p">(</span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">ndNum</span><span class="p">,</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">srcNdStride</span><span class="p">,</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">dstNdStride</span><span class="p">)</span>
</code></pre></div><div data-filter="950"><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 如下原型仅Ascend 950PR/Ascend 950DT支持</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">SetFixpipeNz2ndFlag</span><span class="p">(</span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">ndNum</span><span class="p">,</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">srcNdStride</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">dstNdStride</span><span class="p">)</span>
</code></pre></div></div><h2 id="参数说明">参数说明<a id="zh-cn_topic_0000002516209232_section622mcpsimp"></a><a class="header-anchor" href="#参数说明">​</a></h2><div data-filter="A3,910b,310b"><p>针对如下产品型号，参数说明见下表：</p><div data-filter="A3"><p>Atlas A3 训练系列产品/Atlas A3 推理系列产品</p></div><div data-filter="910b"><p>Atlas A2 训练系列产品/Atlas A2 推理系列产品</p></div><div data-filter="310b"><p>Atlas 200I/500 A2 推理产品</p></div><p><strong>表1</strong> 参数说明</p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>ndNum</td><td>输入</td><td>nd矩阵的数量，取值范围∈[1, 65535]。（<a href="../cube_store_key_features/NZ2ND.html">具体含义图示参见NZ2ND介绍特性章节</a>）</td></tr><tr><td>srcNdStride</td><td>输入</td><td>以分形大小为单位的源步长，源相邻nz矩阵的偏移（头与头）。当ndNum大于1时，取值范围∈[1, 512]；当ndNum配置为1时，srcNdStride可配置为0，此时不生效。单位为1024B。</td></tr><tr><td>dstNdStride</td><td>输入</td><td>目的相邻nd矩阵的偏移（头与头）。取值范围dstNdStride∈[1, 65535]，单位为element元素。</td></tr></tbody></table></div><div data-filter="950"><p>针对Ascend 950PR/Ascend 950DT：</p><p><strong>表2</strong> 参数说明</p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>ndNum</td><td>输入</td><td>nd矩阵的数量，取值范围∈[1, 65535]。（<a href="../cube_store_key_features/NZ2ND.html">具体含义图示参见NZ2ND介绍特性章节</a>）</td></tr><tr><td>srcNdStride</td><td>输入</td><td>以分形大小为单位的源步长，源相邻nz矩阵的偏移（头与头）。当ndNum配置为1时，srcNdStride配置为0即可，不生效。取值范围∈[0, 65535]，单位为C0_SIZE。</td></tr><tr><td>dstNdStride</td><td>输入</td><td>目的相邻nd矩阵的偏移（头与头）。取值范围dstNdStride∈[1, 2^32-1]，单位为element元素。</td></tr></tbody></table></div><div data-filter="x90,9030"><p>针对如下产品型号，参数说明见下表：</p><div data-filter="x90"><p>Kirin X90 处理器系列产品</p></div><div data-filter="9030"><p>Kirin 9030 处理器系列产品</p></div><p><strong>表3</strong> 参数说明</p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>ndNum</td><td>输入</td><td>nd矩阵的数量，取值范围∈[1, 65535]。（<a href="../cube_store_key_features/NZ2ND.html">具体含义图示参见NZ2ND介绍特性章节</a>）</td></tr><tr><td>srcNdStride</td><td>输入</td><td>以分形大小为单位的源步长，源相邻nz矩阵的偏移（头与头）。当ndNum配置为1时，srcNdStride配置为0即可，不生效。取值范围∈[0, 65535]，单位为C0_SIZE。</td></tr><tr><td>dstNdStride</td><td>输入</td><td>目的相邻nd矩阵的偏移（头与头）。取值范围dstNdStride∈[0, 65535]，单位为element元素。</td></tr></tbody></table></div><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><p>参数的数据类型见<a href="#zh-cn_topic_0000002516209232_section620mcpsimp">函数原型</a>。</p><h2 id="返回值说明">返回值说明<a id="section640mcpsimp"></a><a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a id="zh-cn_topic_0000002516209232_section633mcpsimp"></a><a class="header-anchor" href="#约束说明">​</a></h2><ul><li>调用DataCopy接口并且需要进行随路NZ格式转换为ND格式之前，必须先调用SetFixpipeNz2ndFlag设置格式转换配置。</li></ul><h2 id="调用示例">调用示例<a id="section6461234123118"></a><a class="header-anchor" href="#调用示例">​</a></h2><p>完整示例可参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_basic_api/00_data_movement/data_copy_l0c2gm">data_copy_l0c2gm</a>。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">uint16_t</span><span class="w"> </span><span class="n">ndNum</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="kt">uint16_t</span><span class="w"> </span><span class="n">srcNdStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="kt">uint16_t</span><span class="w"> </span><span class="n">dstNdStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetFixpipeNz2ndFlag</span><span class="p">(</span><span class="n">ndNum</span><span class="p">,</span><span class="w"> </span><span class="n">srcNdStride</span><span class="p">,</span><span class="w"> </span><span class="n">dstNdStride</span><span class="p">);</span><span class="w"> </span><span class="c1">// 设置FIX搬运NZ格式到ND格式转换的参数</span>
</code></pre></div></article></div>`,1)])])}const u=s(d,[["render",e]]);export{_ as __pageData,u as default};
